function settleBoard(board: number[][]): number[][] {
  const b = board.map(row => row.slice());
  const R = b.length, C = b[0].length;
  while (true) {
    const mark = Array.from({ length: R }, () => new Array(C).fill(false));
    let found = false;
    for (let i = 0; i < R; i++) {
      for (let j = 0; j < C; j++) {
        const v = b[i][j];
        if (v === 0) continue;
        if (j + 2 < C && b[i][j + 1] === v && b[i][j + 2] === v) { mark[i][j] = mark[i][j + 1] = mark[i][j + 2] = true; found = true; }
        if (i + 2 < R && b[i + 1][j] === v && b[i + 2][j] === v) { mark[i][j] = mark[i + 1][j] = mark[i + 2][j] = true; found = true; }
      }
    }
    if (!found) return b;
    for (let j = 0; j < C; j++) {
      let w = R - 1; // next row to write a surviving candy into
      for (let i = R - 1; i >= 0; i--) {
        if (!mark[i][j] && b[i][j] !== 0) b[w--][j] = b[i][j];
      }
      while (w >= 0) b[w--][j] = 0;
    }
  }
}

