class Solution:
    def settleBoard(self, board: List[List[int]]) -> List[List[int]]:
        b = [row[:] for row in board]
        R, C = len(b), len(b[0])
        while True:
            mark = [[False] * C for _ in range(R)]
            found = False
            for i in range(R):
                for j in range(C):
                    v = b[i][j]
                    if v == 0:
                        continue
                    if j + 2 < C and b[i][j + 1] == v and b[i][j + 2] == v:
                        mark[i][j] = mark[i][j + 1] = mark[i][j + 2] = True
                        found = True
                    if i + 2 < R and b[i + 1][j] == v and b[i + 2][j] == v:
                        mark[i][j] = mark[i + 1][j] = mark[i + 2][j] = True
                        found = True
            if not found:
                return b
            for j in range(C):
                w = R - 1
                for i in range(R - 1, -1, -1):
                    if not mark[i][j] and b[i][j]:
                        b[w][j] = b[i][j]
                        w -= 1
                for i in range(w, -1, -1):
                    b[i][j] = 0

