function settleBoard(board: number[][]): number[][] {
  const b = board.map(row => row.slice());
  const R = b.length, C = b[0].length;
  let found = true;
  while (found) {
    found = false;
    for (let i = 0; i < R; i++) {
      for (let j = 0; j + 2 < C; j++) {
        const v = Math.abs(b[i][j]);
        if (v !== 0 && Math.abs(b[i][j + 1]) === v && Math.abs(b[i][j + 2]) === v) {
          b[i][j] = b[i][j + 1] = b[i][j + 2] = -v;
          found = true;
        }
      }
    }
    for (let j = 0; j < C; j++) {
      for (let i = 0; i + 2 < R; i++) {
        const v = Math.abs(b[i][j]);
        if (v !== 0 && Math.abs(b[i + 1][j]) === v && Math.abs(b[i + 2][j]) === v) {
          b[i][j] = b[i + 1][j] = b[i + 2][j] = -v;
          found = true;
        }
      }
    }
    for (let j = 0; j < C; j++) {
      let w = R - 1;
      for (let i = R - 1; i >= 0; i--) if (b[i][j] > 0) b[w--][j] = b[i][j];
      while (w >= 0) b[w--][j] = 0;
    }
  }
  return b;
}

